package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxFileScanner *bufio.Scanner
var taxFile *os.File

var trRec TaxRec

func formatEdited(val decimal.Decimal, picture string) string {
	// count integer and fractional placeholders
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}

	// work with absolute value (program only positive)
	neg := val.Sign() < 0
	if neg {
		val = val.Neg()
	}

	// total units = val * 10^fracSlots
	// Use Shift to avoid Div
	shifted := val.Shift(int32(fracSlots))
	// shifted may have fractional part due to binary? Truncate toward zero
	shifted = shifted.Truncate(0)
	// Get integer as string with sign handling
	// Use IntPart for absolute already; but for large values use String
	// Convert to integer via decimal -> int64 may overflow, use string
	sStr := shifted.StringFixed(0) // no exponent
	// StringFixed may include minus, but we already handled
	if strings.HasPrefix(sStr, "-") {
		sStr = sStr[1:]
	}
	// sStr is total units in decimal (e.g., 100000 for 1000.00 with 2 frac)
	// Need to split into integer and fractional parts
	// Ensure at least fracSlots+1 digits
	if len(sStr) <= fracSlots {
		// pad with leading zeros
		sStr = strings.Repeat("0", fracSlots+1-len(sStr)) + sStr
	}
	var intPartStr, fracPartStr string
	if fracSlots > 0 {
		intPartStr = sStr[:len(sStr)-fracSlots]
		fracPartStr = sStr[len(sStr)-fracSlots:]
	} else {
		intPartStr = sStr
		fracPartStr = ""
	}
	// intPartStr may be empty -> "0"
	if intPartStr == "" {
		intPartStr = "0"
	}
	// fit to intSlots: keep low-order digits if overflow (high-order truncated)
	var digitsInt string
	if len(intPartStr) > intSlots {
		digitsInt = intPartStr[len(intPartStr)-intSlots:]
	} else if len(intPartStr) < intSlots {
		digitsInt = strings.Repeat("0", intSlots-len(intPartStr)) + intPartStr
	} else {
		digitsInt = intPartStr
	}
	// ensure fracPartStr length fracSlots
	if len(fracPartStr) < fracSlots {
		fracPartStr = strings.Repeat("0", fracSlots-len(fracPartStr)) + fracPartStr
	} else if len(fracPartStr) > fracSlots {
		fracPartStr = fracPartStr[len(fracPartStr)-fracSlots:]
	}

	// Build placeholder type arrays
	// placeholder types for integer part in order left to right
	intPlaceTypes := make([]byte, 0, intSlots)
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intPlaceTypes = append(intPlaceTypes, byte(c))
		}
	}
	// Determine first significant digit index
	firstSig := -1
	for i, ch := range digitsInt {
		if ch != '0' {
			firstSig = i
			break
		}
	}
	if firstSig == -1 {
		// all zero: keep the last position (must be a '9' in these pictures)
		firstSig = intSlots - 1
	}
	// Determine for each integer placeholder whether it is suppressed (space)
	intChars := make([]byte, intSlots) // byte to put (space or digit)
	for i := 0; i < intSlots; i++ {
		d := digitsInt[i]
		pt := intPlaceTypes[i]
		if i < firstSig && pt == 'Z' && d == '0' {
			intChars[i] = ' '
		} else {
			intChars[i] = byte(d)
		}
	}

	// Now build output according to picture
	out := make([]byte, len(picture))
	intIdx := 0
	// For comma handling we need to know if any non-space integer digit exists to the left of the comma
	// We can precompute prefixHasSignificant: for each int placeholder position index, whether there is a non-space char at or before?
	// Instead for each comma, check if all intChars to the left of its logical position are spaces
	// Determine mapping of comma logical position: number of int placeholders before comma
	// Build array of counts
	for pi, ch := range picture {
		switch ch {
		case 'Z', '9':
			out[pi] = intChars[intIdx]
			intIdx++
		case ',':
			// count how many int placeholders are before this picture position
			cntBefore := 0
			for k := 0; k < pi; k++ {
				if picture[k] == 'Z' || picture[k] == '9' {
					cntBefore++
				}
			}
			// check if any intChars[0:cntBefore] is not space
			hasSig := false
			for k := 0; k < cntBefore; k++ {
				if intChars[k] != ' ' {
					hasSig = true
					break
				}
			}
			if hasSig {
				out[pi] = ','
			} else {
				out[pi] = ' '
			}
		case '.':
			out[pi] = '.'
		default:
			out[pi] = byte(ch)
		}
	}
	// Fill fractional placeholders (they are 9's) with frac digits
	fracIdx := 0
	for pi, ch := range picture {
		if dotPos >= 0 && pi > dotPos {
			if ch == 'Z' || ch == '9' {
				if fracIdx < len(fracPartStr) {
					out[pi] = fracPartStr[fracIdx]
					fracIdx++
				}
			}
		}
	}
	if neg {
		// Not needed for this program, but handle sign by placing '-' in last leading space if possible
		// Find rightmost space to replace with '-'
		for i := len(out) - 1; i >= 0; i-- {
			if out[i] == ' ' {
				out[i] = '-'
				break
			}
			if out[i] != ',' && out[i] != '.' {
				break
			}
		}
	}
	return string(out)
}

func formatUneditedInt(val int64, digits int) string {
	s := fmt.Sprintf("%d", val)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

// truncateFit truncates high-order digits to fit PIC 9(n)V99 etc. Used if needed.
func fitDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate to scale first (toward zero)
	v = v.Truncate(scale)
	// Check overflow: integer part digits
	// If overflow, keep low-order digits
	// Compute integer part as abs
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// integer part
	intPart := v.Truncate(0)
	frac := v.Sub(intPart)
	// format intPart as string
	s := intPart.StringFixed(0)
	if len(s) > intDigits {
		s = s[len(s)-intDigits:]
		// rebuild
		newInt, _ := decimal.NewFromString(s)
		v = newInt.Add(frac)
		if neg {
			v = v.Neg()
		}
		return v
	}
	if neg {
		v = v.Neg()
	}
	return v
}

func READPARA() {
	if taxFileScanner.Scan() {
		line := taxFileScanner.Text()
		// Pad with spaces on right if shorter than record length 13
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		trRec.TrId = line[0:5]
		incStr := line[5 : 5+8]
		incStr = strings.TrimSpace(incStr)
		if incStr == "" {
			incStr = "0"
		}
		// incStr contains digits only, implied V99
		// Parse as integer
		var n int64
		// may contain leading zeros; parse
		for _, ch := range incStr {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		trRec.TrIncome = decimal.NewFromInt(n).Shift(-2)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	limit10000 := decimal.NewFromInt(10000)
	limit40000 := decimal.NewFromInt(40000)
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)
	rate10 := decimal.NewFromFloat(0.10)
	rate20 := decimal.NewFromFloat(0.20)
	rate30 := decimal.NewFromFloat(0.30)

	if trRec.TrIncome.Cmp(limit10000) <= 0 {
		WsTax = trRec.TrIncome.Mul(rate10).Round(2)
	} else {
		if trRec.TrIncome.Cmp(limit40000) <= 0 {
			diff := trRec.TrIncome.Sub(limit10000)
			WsTax = thousand.Add(diff.Mul(rate20)).Round(2)
		} else {
			diff := trRec.TrIncome.Sub(limit40000)
			WsTax = sevenThousand.Add(diff.Mul(rate30)).Round(2)
		}
	}
	// COMPUTE WS-NET = TR-INCOME - WS-TAX (truncated)
	WsNet = trRec.TrIncome.Sub(WsTax).Truncate(2)
	WsTax = fitDecimal(WsTax, 7, 2)
	WsNet = fitDecimal(WsNet, 7, 2)

	WsTotalTax = WsTotalTax.Add(WsTax)
	WsTotalTax = fitDecimal(WsTotalTax, 9, 2)
	WsCount = WsCount + 1

	WsIncEd = formatEdited(trRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	// DISPLAY TR-ID " " WS-INC-ED " " WS-TAX-ED " " WS-NET-ED
	fmt.Printf("%s %s %s %s\n", trRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	READPARA()
}

func MAINPARA() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer taxFile.Close()
	taxFileScanner = bufio.NewScanner(taxFile)
	// Allow large lines; set buffer
	buf := make([]byte, 0, 64*1024)
	taxFileScanner.Buffer(buf, 1024*1024)

	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	// CLOSE is deferred
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func main() {
	MAINPARA()
}

